/* Natural pixel coordinates of each pill within skillsToolsArt (2400x588),
   measured directly from the artwork so hover hit-areas line up exactly
   with the printed pills — no part of the image is redrawn or retyped. */
const SKILLS_ART_WIDTH = 2400;
const SKILLS_ART_HEIGHT = 588;
const pillRegions = [
  { label: "UX/UI", box: [0, 163, 165, 269] },
  { label: "UX Research", box: [205, 163, 503, 269] },
  { label: "Wireframing & Prototyping", box: [544, 163, 1093, 269] },
  { label: "Motion & Video", box: [1133, 163, 1475, 269] },
  { label: "Visual Design", box: [1515, 163, 1826, 269] },
  { label: "Social Media", box: [1866, 163, 2163, 269] },
  { label: "Figma", box: [0, 323, 239, 429] },
  { label: "Figjam", box: [279, 323, 531, 429] },
  { label: "Adobe After Effects", box: [571, 323, 1068, 429] },
  { label: "Premiere Pro", box: [1108, 323, 1478, 429] },
  { label: "DaVinci Resolve", box: [1518, 323, 1941, 429] },
  { label: "Canva", box: [1981, 323, 2228, 429] },
  { label: "Claude", box: [0, 484, 257, 588] },
  { label: "Tableau", box: [297, 484, 572, 588] },
  { label: "Power BI", box: [612, 484, 905, 588] },
  { label: "KNIME", box: [945, 484, 1199, 588] },
];

/* Renders invisible hit-areas over the flattened skills+tools artwork.
   Each hit-area shows a windowed crop of the SAME image (via a
   background-image sprite offset) so hovering can lift/glow an
   individual pill without redrawing, retyping, or altering a single
   pixel of the original asset. Positions are measured with a
   ResizeObserver so they track the image's rendered width exactly,
   at any breakpoint. */
function InteractiveSkillsArt() {
  const wrapRef = useRef(null);
  const [scale, setScale] = useState(0);

  useEffect(() => {
    const el = wrapRef.current;
    if (!el) return;
    const update = () => setScale(el.offsetWidth / SKILLS_ART_WIDTH);
    update();
    const ro = new ResizeObserver(update);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  return (
    <div ref={wrapRef} className="relative w-full">
      <img
        src={skillsToolsArt}
        alt="Skills and tools: UX/UI, UX Research, Wireframing & Prototyping, Motion & Video, Visual Design, Social Media, Figma, Figjam, Adobe After Effects, Premiere Pro, DaVinci Resolve, Canva, Claude, Tableau, Power BI, KNIME"
        className="w-full h-auto block"
      />
      {scale > 0 &&
        pillRegions.map(({ label, box }) => {
          const [x0, y0, x1, y1] = box;
          const w = (x1 - x0) * scale;
          const h = (y1 - y0) * scale;
          return (
            <div
              key={label}
              className="pill-hit"
              role="img"
              aria-label={label}
              style={{
                left: x0 * scale,
                top: y0 * scale,
                width: w,
                height: h,
                backgroundImage: `url(${skillsToolsArt})`,
                backgroundSize: `${SKILLS_ART_WIDTH * scale}px ${SKILLS_ART_HEIGHT * scale}px`,
                backgroundPosition: `${-x0 * scale}px ${-y0 * scale}px`,
              }}
            />
          );
        })}
    </div>
  );
}

